int add_route_ipv6(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int err;

    if ((info->nlflags & NLM_F_CREATE) == 0 && (info->nlflags & NLM_F_REPLACE) == 0) {
        return -EINVAL;
    }

    err = fib6_add_1(root, rt, info);
    if (err < 0)
        return err;

    if (rt->rt6i_src) {
        struct fib6_node *subtree = NULL;

        subtree = fib6_node_create_subtree(root, rt->rt6i_src);
        if (!subtree) {
            fib6_remove_route(rt);
            return -ENOMEM;
        }

        err = fib6_add_source_route(subtree, rt);
        if (err < 0) {
            fib6_remove_route(rt);
            fib6_repair_tree(subtree);
            return err;
        }
    }

    rt6_info_acquire(rt);
    return 0;
}

int add_fib6_route(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int err;

    if (!(info->nlflags & (RTM_F_CREATE | RTM_F_REPLACE)))
        return -EINVAL;

    err = fib6_add_1(root, rt, info);
    if (err < 0)
        return err;

    if (rt->rt6i_src) {
        struct fib6_node *subtree;

        subtree = fib6_node_create_subtree(root, rt->rt6i_src);
        if (!subtree) {
            return -ENOMEM;
        }

        rt->rt6i_node = subtree;
        fib6_add_1(subtree, rt, info);
    }

    rt6_info_hold(rt);

    if (err == 0)
        return 0;

    rt6_info_release(rt);
    fib6_repair_tree(root, rt);

    return err;
}

int add_route_to_fib6(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int err;

    if ((info->nl_net->event & RTM_NEWRULE) && !(info->nl_net->flags & RTM_F_CLONED)) {
        return -EINVAL;
    }

    err = fib6_add_1(root, rt, info);
    if (err < 0)
        return err;

    if (rt->rt6i_src) {
        struct fib6_node *subtree = fib6_node_alloc();
        if (!subtree)
            return -ENOMEM;

        err = fib6_insert_subtree(root, subtree);
        if (err < 0) {
            kfree(subtree);
            return err;
        }

        err = add_src_route(subtree, rt, info);
        if (err < 0) {
            fib6_remove_subtree(root, subtree);
            kfree(subtree);
            return err;
        }
    }

    rt6_add_ref(rt);

    return 0;
}
